//! Collapses the raw `target_*` cfg keys onto a small set of semantic aliases.
//!
//! Doing the platform detection here means the library source never has to
//! juggle `target_os`, `target_family`, `target_arch` or `target_env` again.
//! It just asks whether `platform_unix`, `platform_windows`, `platform_wasm`
//! or `platform_other` is active.
//!
//! Exactly one alias is emitted for any given target.

/// Every alias this build script may emit. Used both for `check-cfg` and as
/// the single source of truth for what counts as a known platform.
const ALIASES: &[&str] = &[
    "platform_unix",
    "platform_windows",
    "platform_wasm",
    "platform_other",
];

fn main() {
    for alias in ALIASES {
        // Tell rustc these cfgs are expected, so `unexpected_cfgs` stays quiet.
        println!("cargo::rustc-check-cfg=cfg({alias})");
    }

    println!("cargo::rustc-cfg={}", select_alias(&target_families()));
}

/// Pick the single alias that matches the target's OS families.
fn select_alias(families: &[String]) -> &'static str {
    let has = |family: &str| families.iter().any(|f| f == family);

    // wasm is checked first: a few wasm targets also report another family,
    // and the wasm implementation is the more specific one.
    if has("wasm") {
        "platform_wasm"
    } else if has("unix") {
        "platform_unix"
    } else if has("windows") {
        "platform_windows"
    } else {
        "platform_other"
    }
}

/// The target's OS families, e.g. `["unix"]` or `["wasm"]`.
///
/// `CARGO_CFG_TARGET_FAMILY` is comma-separated when a target belongs to more
/// than one family.
fn target_families() -> Vec<String> {
    std::env::var("CARGO_CFG_TARGET_FAMILY")
        .unwrap_or_default()
        .split(',')
        .filter(|family| !family.is_empty())
        .map(str::to_owned)
        .collect()
}

//! A small cross-platform library that shows how to keep conditional
//! compilation clean and readable across many targets.
//!
//! # The pattern
//!
//! Platform detection happens **once**, in `build.rs`, which maps the raw
//! `CARGO_CFG_TARGET_*` environment variables onto a single semantic alias:
//!
//! | Alias              | Targets                                |
//! |--------------------|----------------------------------------|
//! | `platform_unix`    | `unix` family (Linux, macOS, BSD, ...) |
//! | `platform_windows` | `windows` family                       |
//! | `platform_wasm`    | `wasm` family (WASI and bare wasm)     |
//! | `platform_other`   | everything else                        |
//!
//! From then on the crate only ever tests those aliases. Each platform has one
//! module that provides the same set of items, selected through the `imp`
//! alias in [`platform`]. Adding a platform means adding one module and one
//! arm in the build script, not hunting down `#[cfg]`s scattered everywhere.
//!
//! # Example
//!
//! ```
//! use multiplatform::{line_ending, path_separator, Platform};
//!
//! let separator = match multiplatform::PLATFORM {
//!     Platform::Windows => '\\',
//!     _ => '/',
//! };
//! assert_eq!(path_separator(), separator);
//! assert!(!line_ending().is_empty());
//! ```

mod platform;

pub use platform::Platform;
pub use platform::imp::{line_ending, path_separator};

/// The platform this crate was compiled for.
///
/// This is a `const`, so it can be used in constant contexts and is resolved
/// entirely at compile time.
pub const PLATFORM: Platform = platform::imp::PLATFORM;

